SELECT * FROM (SELECT CASE WHEN unit_price >= 360 THEN 'high' WHEN unit_price >= 170 THEN 'mid' ELSE 'low' END AS unit_price_bucket, COUNT(DISTINCT quantity) AS unique_orders FROM order_items GROUP BY CASE WHEN unit_price >= 360 THEN 'high' WHEN unit_price >= 170 THEN 'mid' ELSE 'low' END) AS x WHERE unique_orders > 9
